package cn.zhuatech.llmops.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ModelDeploymentGovernanceService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.evaluationThresholdPassed())b.add("离线评测未达到发布阈值");if(!r.redTeamCompleted())b.add("安全红队测试未完成");if(!r.privacyAssessmentPassed())b.add("隐私影响评估未通过");if(!r.modelAndPromptVersioned())b.add("模型与提示词未版本化");if(r.openCriticalSafetyIssues()>0)b.add("存在未关闭的严重安全问题");if(!r.ownerAndApproverAssigned())b.add("未配置模型责任人与审批人");if(!b.isEmpty()){a.add("阻断上线并关闭评测、安全、隐私和治理问题");return new Assessment(Decision.BLOCKED,b,a);}if(!r.rollbackReady()||!r.fallbackModelReady()||r.predictedBudgetUsagePercent()>90){if(!r.rollbackReady())a.add("验证模型和提示词回滚");if(!r.fallbackModelReady())a.add("配置降级模型或规则兜底");if(r.predictedBudgetUsagePercent()>90)a.add("执行成本复核与限流方案");return new Assessment(Decision.CANARY,b,a);}a.add("批准分阶段上线并冻结评测与配置快照");return new Assessment(Decision.DEPLOY,b,a);}public record Request(@NotBlank String releaseId,boolean evaluationThresholdPassed,boolean redTeamCompleted,boolean privacyAssessmentPassed,boolean modelAndPromptVersioned,@Min(0)int openCriticalSafetyIssues,boolean ownerAndApproverAssigned,boolean rollbackReady,boolean fallbackModelReady,@Min(0)int predictedBudgetUsagePercent){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{DEPLOY,CANARY,BLOCKED}}
